  gorsel: "<svg viewBox=\"0 0 380 150\" role=\"img\" aria-label=\"Yol: yatay 150 m, dikey 30 m\"><polygon points=\"30,120 330,120 330,62\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\"/><polyline points=\"318,120 318,108 330,108\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"180\" y=\"144\" font-size=\"15\" text-anchor=\"middle\" fill=\"currentColor\">150 m</text><text x=\"340\" y=\"96\" font-size=\"15\" fill=\"currentColor\">30 m</text></svg>",
  secenekler: ["[[1|6]]","[[1|5]]","[[1|4]]","5"],
